"""Prepare and score a small, structure-disjoint evidence benchmark offline."""

import argparse
import csv
import hashlib
import json
import shutil
import struct
import zlib
from pathlib import Path

DATA = Path(__file__).resolve().parent / "data"
LABELS = ("consistent", "conflict", "insufficient")
# Gold authored from the archived atom records, not generated by either baseline.
ENTRIES = {
    "1crn": ("dev", "A", "A", [("7", "", "7"), ("8", "", "8"), ("9", "", "9")]),
    "3b9f": ("test", "H", "B", [("77", "A", "73"), ("78", "", "74"), ("79", "", "75")]),
}
ROW_KEYS = ("r17", "r06", "r31")


def write_json(path, value):
    with path.open("x", encoding="utf-8", newline="\n") as f:
        json.dump(value, f, indent=2, ensure_ascii=False)
        f.write("\n")


def read_json(path):
    return json.loads(path.read_text(encoding="utf-8"))


def diagram():
    """Three-node index diagram, not a rendering of molecular geometry."""
    def chunk(tag, data):
        return struct.pack(">I", len(data)) + tag + data + struct.pack(">I", zlib.crc32(tag + data))

    width, height = 144, 48
    rows = bytearray()
    for y in range(height):
        rows.append(0)
        for x in range(width):
            node = any((x - cx) ** 2 + (y - 24) ** 2 <= 11 ** 2 for cx in (24, 72, 120))
            edge = 24 <= x <= 120 and 23 <= y <= 25
            rows.extend((31, 105, 118) if node else (132, 153, 160) if edge else (245, 248, 249))
    return (b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", struct.pack(">2I5B", width, height, 8, 2, 0, 0, 0))
            + chunk(b"IDAT", zlib.compress(rows)) + chunk(b"IEND", b""))


def reference(path):
    return {"path": path.name, "sha256": hashlib.sha256(path.read_bytes()).hexdigest()}


def prepare(root):
    root.mkdir(parents=True, exist_ok=False)
    index, gold = [], {}
    for entry, (split, auth_chain, label_chain, residues) in ENTRIES.items():
        for site in (0, 1):
            for variant, answer in enumerate(LABELS):
                uid = hashlib.sha256(f"rt1/{entry}/{site}/{variant}".encode()).hexdigest()[:12]
                directory = root / "inputs" / uid
                directory.mkdir(parents=True)
                structure, figure, table = (directory / name for name in ("excerpt.cif", "diagram.png", "table.csv"))
                shutil.copyfile(DATA / f"{entry}.cif", structure)
                figure.write_bytes(diagram())
                with table.open("x", newline="", encoding="utf-8") as f:
                    writer = csv.writer(f)
                    writer.writerow(["row_key", "model", "label_asym_id", "label_seq_id"])
                    target = site + int(answer == "conflict")
                    writer.writerow([ROW_KEYS[site], 1, label_chain, residues[target][2]])
                num, ins, _ = residues[site]
                claim = {"model": 1, "auth_asym_id": auth_chain, "auth_seq_id": num, "ins_code": ins}
                if answer == "insufficient":
                    del claim["auth_asym_id"]
                region = {"id": "selection", "rect": [10 + 48 * site, 10, 28, 28], "claim": claim,
                          "row_key": ROW_KEYS[site]}
                manifest = {"schema_version": 1, "structure": reference(structure), "figure": reference(figure),
                            "table": reference(table), "regions": [region]}
                write_json(directory / "manifest.json", manifest)
                index.append({"id": uid, "entry": entry, "split": split, "manifest": f"inputs/{uid}/manifest.json"})
                gold[uid] = answer
    write_json(root / "index.json", sorted(index, key=lambda x: x["id"]))
    write_json(root / "gold.json", gold)


def literal(path):
    manifest = read_json(path)
    region, = manifest["regions"]
    claim = region["claim"]
    with (path.parent / manifest["table"]["path"]).open(newline="", encoding="utf-8") as f:
        row, = [r for r in csv.DictReader(f) if r["row_key"] == region["row_key"]]
    if not all(k in claim for k in ("auth_asym_id", "auth_seq_id", "ins_code")):
        return "insufficient"
    left = (claim["auth_asym_id"], claim["auth_seq_id"], claim["ins_code"])
    return "consistent" if left == (row["label_asym_id"], row["label_seq_id"], "") else "conflict"


def mapped(path):
    from residuetrace import audit
    result = audit(path)
    region, = result["regions"]
    if region["status"] == "verified" and not result["ok"]:
        raise ValueError("A benchmark input has an unexpected bundle-level failure")
    return {"verified": "consistent", "conflict": "conflict", "undeclared": "insufficient",
            "ambiguous": "insufficient", "unknown": "insufficient"}[region["status"]]


def score(items, gold, predictions):
    ids = {x["id"] for x in items}
    if not items or len(ids) != len(items) or set(predictions) != ids:
        raise ValueError("Expected exactly one prediction for every requested item and no extras")
    if any(p not in LABELS for p in predictions.values()):
        raise ValueError(f"Allowed predictions: {LABELS}")
    by_label = {label: {"correct": 0, "total": 0} for label in LABELS}
    for key in ids:
        bucket = by_label[gold[key]]
        bucket["total"] += 1
        bucket["correct"] += int(predictions[key] == gold[key])
    return {"correct": sum(b["correct"] for b in by_label.values()), "total": len(items), "by_label": by_label}


def predictions_file(path):
    def unique(pairs):
        result = dict(pairs)
        if len(result) != len(pairs):
            raise ValueError("Duplicate prediction ID")
        return result
    data = json.loads(path.read_text(encoding="utf-8"), object_pairs_hook=unique)
    if not isinstance(data, dict):
        raise ValueError("Expected a JSON object keyed by item ID")
    return data


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    commands = parser.add_subparsers(dest="command", required=True)
    commands.add_parser("prepare").add_argument("root", type=Path)
    run = commands.add_parser("run")
    run.add_argument("root", type=Path)
    run.add_argument("--split", choices=("dev", "test"), required=True)
    options = run.add_mutually_exclusive_group(required=True)
    options.add_argument("--baseline", choices=("literal", "mapped"))
    options.add_argument("--predictions", type=Path)
    args = parser.parse_args()
    if args.command == "prepare":
        prepare(args.root)
        return
    items = [i for i in read_json(args.root / "index.json") if i["split"] == args.split]
    if args.predictions:
        predictions = predictions_file(args.predictions)
    else:
        baseline = literal if args.baseline == "literal" else mapped
        predictions = {i["id"]: baseline(args.root / i["manifest"]) for i in items}
    print(json.dumps(score(items, read_json(args.root / "gold.json"), predictions), indent=2))


if __name__ == "__main__":
    main()
